function validate([board, hand]) {
  if (typeof board !== 'string' || board.length < 1 || board.length > 16) return 'board holds 1 to 16 balls.';
  if (typeof hand !== 'string' || hand.length < 1 || hand.length > 5) return 'hand holds 1 to 5 balls.';
  if (!/^[RYBGW]+$/.test(board) || !/^[RYBGW]+$/.test(hand)) return "Balls are 'R', 'Y', 'B', 'G' or 'W'.";
  if (/(.)\1\1/.test(board)) return 'board must not start with three equal balls in a row.';
  return null;
}

