function findMinStep(board, hand) {
  // Remove the run around index at, then any run formed where the two sides meet.
  const collapse = (row, at) => {
    let left = at;
    let right = at;
    while (left >= 0 && right < row.length && row[left] === row[right]) {
      let start = left;
      let end = right;
      while (start > 0 && row[start - 1] === row[left]) start--;
      while (end < row.length - 1 && row[end + 1] === row[right]) end++;
      if (end - start + 1 < 3) break;
      row = row.slice(0, start) + row.slice(end + 1);
      left = start - 1;
      right = start;
    }
    return row;
  };

  const sorted = [...hand].sort().join('');
  const seen = new Set([board + ' ' + sorted]);
  let queue = [[board, sorted]];
  for (let steps = 1; queue.length > 0; steps++) {
    const next = [];
    for (const [row, balls] of queue) {
      for (let i = 0; i <= row.length; i++) {
        for (let j = 0; j < balls.length; j++) {
          const color = balls[j];
          if (j > 0 && color === balls[j - 1]) continue;
          if (i > 0 && row[i - 1] === color) continue;
          const grows = row[i] === color;
          const splits = i > 0 && row[i - 1] === row[i];
          if (!grows && !splits) continue;
          const after = collapse(row.slice(0, i) + color + row.slice(i), i);
          if (after === '') return steps;
          const rest = balls.slice(0, j) + balls.slice(j + 1);
          const key = after + ' ' + rest;
          if (seen.has(key)) continue;
          seen.add(key);
          next.push([after, rest]);
        }
      }
    }
    queue = next;
  }
  return -1;
}

