function findMinStep(board, hand) {
  // Try every ball of the hand at every position, with no pruning, memoised on (row, hand).
  const shrink = row => {
    for (;;) {
      let found = false;
      for (let i = 0; i < row.length && !found; ) {
        let j = i;
        while (j < row.length && row[j] === row[i]) j++;
        if (j - i >= 3) { row = row.slice(0, i) + row.slice(j); found = true; }
        i = j;
      }
      if (!found) return row;
    }
  };
  const memo = new Map();
  const best = (row, balls) => {
    if (row === '') return 0;
    if (balls === '') return Infinity;
    const key = row + '|' + balls;
    if (memo.has(key)) return memo.get(key);
    let result = Infinity;
    for (let j = 0; j < balls.length; j++) {
      if (j > 0 && balls[j] === balls[j - 1]) continue;
      const rest = balls.slice(0, j) + balls.slice(j + 1);
      for (let i = 0; i <= row.length; i++) result = Math.min(result, 1 + best(shrink(row.slice(0, i) + balls[j] + row.slice(i)), rest));
    }
    memo.set(key, result);
    return result;
  };
  const answer = best(board, [...hand].sort().join(''));
  return answer === Infinity ? -1 : answer;
}

