function generate(rand, size) {
  const palette = ['R', 'Y', 'B', 'G', 'W'];
  for (let i = palette.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [palette[i], palette[j]] = [palette[j], palette[i]];
  }
  // Two or three colors give a good mix of clearable and hopeless rows; sometimes allow more.
  const count = rand() < 0.15 ? 4 + Math.floor(rand() * 2) : 2 + Math.floor(rand() * 2);
  const colors = palette.slice(0, count);
  const pick = () => colors[Math.floor(rand() * colors.length)];
  const length = size === 'large' ? 12 + Math.floor(rand() * 5) : 1 + Math.floor(rand() * 8);
  let board = '';
  while (board.length < length) {
    const color = pick();
    if (board.length >= 2 && board[board.length - 1] === color && board[board.length - 2] === color) continue;
    board += color;
  }
  const handSize = size === 'large' ? 5 : 1 + Math.floor(rand() * 4);
  let hand = '';
  for (let k = 0; k < handSize; k++) hand += rand() < 0.1 ? palette[Math.floor(rand() * 5)] : pick();
  return [board, hand];
}
